/* ==FMP Plugin==
{
  "id": "youtube",
  "name": "YouTube",
  "version": "1.6.0",
  "author": "FMP",
  "description": "搜尋 YouTube 影片並播放其音訊，可匯入播放清單與瀏覽「本週新歌」榜單。",
  "apiVersion": 1,
  "capabilities": [
    "search",
    "resolveStream",
    "mix",
    "trackDetail",
    "importPlaylist",
    "libraryRead",
    "libraryWrite",
    "charts",
    "login"
  ],
  "allowedHosts": [
    "youtube.com",
    "googlevideo.com",
    "ytimg.com",
    "ggpht.com",
    "accounts.google.com"
  ],
  "login": {
    "methods": [
      "webView",
      "cookie"
    ],
    "webView": {
      "url": "https://accounts.google.com/ServiceLogin?service=youtube&continue=https://www.youtube.com/",
      "cookieHosts": [
        "https://www.youtube.com"
      ],
      "doneCookies": [
        "SAPISID",
        "__Secure-1PSID",
        "__Secure-3PSID"
      ]
    },
    "automationRisk": true
  },
  "redaction": {
    "headerNames": [
      "X-Goog-Visitor-Id"
    ],
    "keyNames": [
      "visitorData"
    ]
  }
}
==/FMP Plugin== */
